/* Score Your Chores printable chart maker. No tracking, nothing leaves the page. */
(function () {
  "use strict";
  var D = window.__SYC;
  var days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  var themes = {
    bubblegum: { name: "Bubblegum", strong: "#C92F7C", main: "#F4579E", soft: "#FFE0F0", page: "#FFF0F7", border: "#F7D3E5" },
    orange: { name: "Orange", strong: "#C4500F", main: "#FF8A3D", soft: "#FFE6D6", page: "#FFF4EC", border: "#F9D8C2" },
    sky: { name: "Sky", strong: "#1E6FB8", main: "#3AA7F5", soft: "#DDF0FF", page: "#EEF7FF", border: "#CBE4F7" },
    lime: { name: "Lime", strong: "#237A2C", main: "#58C23A", soft: "#E2F7D9", page: "#F1FBEC", border: "#CDEBC0" },
    sunshine: { name: "Sunshine", strong: "#8A5A00", main: "#FFC31F", soft: "#FFF1C7", page: "#FFF9E6", border: "#F5E0A0" },
    grape: { name: "Grape", strong: "#5A3FD6", main: "#8F7BFF", soft: "#ECE7FF", page: "#F5F2FF", border: "#DCD3FB" },
  };
  var buddyNames = { pip: "Pip", nimbus: "Nimbus", bolt: "Bolt", mochi: "Mochi", pebble: "Pebble", twinkle: "Twinkle" };
  var maxChores = 8;

  function esc(text) {
    return String(text).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  // "Time for A trip to the park" reads badly, so a leading article is lower-cased after "Time for".
  function afterTimeFor(reward) {
    return /^(A|An|The|Some|Our|My) /.test(reward) ? reward.charAt(0).toLowerCase() + reward.slice(1) : reward;
  }

  function buddySvg(kind, cls) {
    return '<svg class="' + (cls || "") + '" viewBox="0 0 120 120" aria-hidden="true">' + D.buddies[kind] + "</svg>";
  }
  function iconSvg(name, color, cls) {
    var d = D.icons[name] || D.icons.star;
    var filled = name === "star" || name === "sparkle" || name === "flame";
    return (
      '<svg class="' + (cls || "") + '" viewBox="0 0 24 24" aria-hidden="true"><path d="' + d + '" fill="' + (filled ? color : "none") +
      '" stroke="' + (filled ? "none" : color) + '" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
    );
  }
  function possessive(name) {
    var n = name.trim();
    if (!n) return "My";
    return esc(n) + (/s$/i.test(n) ? "’" : "’s");
  }
  function footer(t) {
    return (
      '<div class="sheet-brand"><div class="sheet-qr">' + D.qr + '</div><div><strong>Made with Score Your Chores</strong>' +
      "<span>The free chore chart app for " + (D.androidLive ? "iPhone and Android" : "iPhone") + ". Scan to get it, or visit scoreyourchores.com</span></div></div>"
    );
  }

  /* ------------------------------------------------------------ chore chart */
  function choreSheet(s) {
    var t = themes[s.theme];
    var rows = s.chores.length ? s.chores : [{ title: "Your first quest", icon: "star" }];
    var rowH = Math.max(11, Math.min(17, 120 / rows.length - 1.8));
    var html =
      '<div class="sheet sheet-landscape" style="--strong:' + t.strong + ";--main:" + t.main + ";--soft:" + t.soft + ";--page:" + t.page + ";--border:" + t.border + '">' +
      '<div class="sheet-head">' + buddySvg(s.buddy, "sheet-buddy") +
      '<div class="sheet-title"><p class="sheet-eyebrow">' + esc(buddyNames[s.buddy]) + " and " + (s.name.trim() ? esc(s.name.trim()) : "me") + "</p>" +
      "<h2>" + possessive(s.name) + " " + esc(s.heading || "Quest Chart") + "</h2><p>" + esc(s.subline || "Finish a quest, add a tick or a sticker. Every tick counts!") + "</p></div>" +
      '<div class="sheet-week"><span>Week of</span><i></i></div></div>' +
      '<div class="sheet-grid" style="--rowh:' + rowH + 'mm"><div class="grid-corner">Quest</div>';
    days.forEach(function (d) {
      html += '<div class="grid-day">' + d + "</div>";
    });
    rows.forEach(function (c) {
      html += '<div class="grid-chore"><span class="chip">' + iconSvg(c.icon, t.strong) + "</span><span>" + esc(c.title) + "</span></div>";
      days.forEach(function () {
        html += '<div class="grid-box"><i></i></div>';
      });
    });
    html +=
      '</div><div class="sheet-foot"><div class="sheet-goal">' + iconSvg("gift", t.strong) +
      "<span>Saving up for</span><i>" + esc(s.goal || "") + "</i></div>" + footer(t) + "</div></div>";
    return html;
  }

  /* ----------------------------------------------------------- reward chart */
  function rewardSheet(s) {
    var t = themes[s.theme];
    var n = s.squares;
    var cols = n <= 10 ? 4 : n <= 20 ? 5 : 6;
    var dot = n <= 10 ? 38 : n <= 15 ? 32 : n <= 20 ? 30 : 25;
    var html =
      '<div class="sheet sheet-portrait" style="--strong:' + t.strong + ";--main:" + t.main + ";--soft:" + t.soft + ";--page:" + t.page + ";--border:" + t.border + '">' +
      '<div class="sheet-head">' + buddySvg(s.buddy, "sheet-buddy") +
      '<div class="sheet-title"><p class="sheet-eyebrow">' + esc(buddyNames[s.buddy]) + " is cheering you on</p><h2>" + possessive(s.name) + " " + esc(s.heading || "Reward Chart") + "</h2>" +
      "<p>" + esc(s.subline || "One sticker for every time. Fill them all to win!") + "</p></div></div>" +
      '<div class="reward-goal">' + iconSvg("trophy", t.strong) + "<div><span>Road to</span><strong>" + esc(s.reward.trim() || "_______________") + "</strong></div></div>" +
      '<div class="reward-grid" style="--cols:' + cols + ";--dot:" + dot + 'mm">';
    for (var i = 1; i <= n; i++) {
      var star = i % 5 === 0;
      html += '<div class="reward-dot' + (star ? " is-star" : "") + '"><span>' + i + "</span></div>";
    }
    html += '</div><div class="reward-prize">' + buddySvg(s.buddy, "prize-buddy") + "<div><strong>You did it!</strong><span>Time for " + esc(afterTimeFor(s.reward.trim()) || "your reward") + "</span></div></div>";
    html += '<div class="sheet-foot">' + footer(t) + "</div></div>";
    return html;
  }

  /* ------------------------------------------ prefilled from the app's link */
  // The app opens this page with ?name=&buddy=&theme=&age=&chores=Title~icon|Title~icon so a child's chart is ready to print.
  function applyLink(state, kind) {
    var q;
    try {
      q = new URLSearchParams(window.location.search);
    } catch (e) {
      return;
    }
    var name = q.get("name");
    if (name) state.name = name.slice(0, 16);
    var buddy = q.get("buddy");
    if (buddy && buddyNames[buddy]) state.buddy = buddy;
    var theme = q.get("theme");
    if (theme && themes[theme]) state.theme = theme;
    var age = q.get("age");
    if (age && D.ages[age]) state.age = age;
    var goal = q.get("goal");
    if (goal) state.goal = goal.slice(0, 30);
    var reward = q.get("reward");
    if (reward) state.reward = reward.slice(0, 30);
    var chores = q.get("chores");
    if (kind === "chores" && chores) {
      var list = chores
        .split("|")
        .map(function (item) {
          var parts = item.split("~");
          var title = (parts[0] || "").trim().slice(0, 28);
          var icon = parts[1] && D.icons[parts[1]] ? parts[1] : "star";
          return title ? { title: title, icon: icon } : null;
        })
        .filter(Boolean)
        .slice(0, maxChores);
      if (list.length) state.chores = list;
    }
  }

  /* --------------------------------------------------------------- controls */
  function mount(root) {
    var kind = root.getAttribute("data-kind") || "chores";
    var age = root.getAttribute("data-age") || "6_8";
    var themeIds = Object.keys(themes);
    var state = {
      name: "",
      buddy: root.getAttribute("data-buddy") || "mochi",
      theme: root.getAttribute("data-theme") || "bubblegum",
      age: age,
      chores: [],
      goal: root.getAttribute("data-goal") || "",
      reward: root.getAttribute("data-reward") || "",
      squares: [10, 15, 20, 30].indexOf(+root.getAttribute("data-squares")) >= 0 ? +root.getAttribute("data-squares") : 10,
      heading: root.getAttribute("data-heading") || "",
      subline: root.getAttribute("data-subline") || "",
    };
    function suggestions() {
      return D.ages[state.age] ? D.ages[state.age].chores : [];
    }
    function pickDefaults() {
      var a = D.ages[state.age];
      state.chores = suggestions().slice(0, a ? a.defaults : 5).map(function (c) {
        return { title: c[0], icon: c[1] };
      });
    }
    if (kind === "chores") pickDefaults();
    var preset = root.getAttribute("data-chores");
    if (kind === "chores" && preset) {
      state.chores = preset.split("|").map(function (item) {
        var parts = item.split("~");
        return { title: parts[0], icon: D.icons[parts[1]] ? parts[1] : "star" };
      });
    }
    applyLink(state, kind);

    var controls = document.createElement("div");
    controls.className = "maker-controls";
    var previewWrap = document.createElement("div");
    previewWrap.className = "maker-preview";
    var stage = document.createElement("div");
    stage.className = "maker-stage";
    previewWrap.appendChild(stage);
    root.appendChild(controls);
    root.appendChild(previewWrap);

    function field(label, inner) {
      // Text boxes sit inside a <label> so screen readers announce the field name.
      var tag = inner.indexOf("<input") === 0 ? "label" : "div";
      return "<" + tag + ' class="field"><span class="field-label">' + label + "</span>" + inner + "</" + tag + ">";
    }
    function renderControls() {
      var html = field(
        "Child’s name",
        '<input type="text" maxlength="16" autocomplete="off" data-k="name" placeholder="e.g. Mia" value="' + esc(state.name) + '" />'
      );
      html += field(
        "Pick a Buddy",
        '<div class="buddy-pick" role="radiogroup" aria-label="Buddy">' +
          Object.keys(buddyNames)
            .map(function (b) {
              return '<button type="button" role="radio" aria-checked="' + (state.buddy === b) + '" data-buddy="' + b + '" title="' + buddyNames[b] + '">' + buddySvg(b) + "<span>" + buddyNames[b] + "</span></button>";
            })
            .join("") +
          "</div>"
      );
      html += field(
        "Colour",
        '<div class="theme-pick" role="radiogroup" aria-label="Colour">' +
          themeIds
            .map(function (id) {
              return '<button type="button" role="radio" aria-checked="' + (state.theme === id) + '" aria-label="' + themes[id].name + '" data-theme="' + id + '" style="--sw:' + themes[id].main + '"></button>';
            })
            .join("") +
          "</div>"
      );
      if (kind === "chores") {
        html += field(
          "Age",
          '<div class="seg" role="radiogroup" aria-label="Age">' +
            Object.keys(D.ages)
              .map(function (id) {
                return '<button type="button" role="radio" aria-checked="' + (state.age === id) + '" data-age="' + id + '">' + D.ages[id].short + "</button>";
              })
              .join("") +
            "</div>"
        );
        var chosen = {};
        state.chores.forEach(function (c) {
          chosen[c.title] = true;
        });
        var list = suggestions().map(function (c) {
          return { title: c[0], icon: c[1] };
        });
        state.chores.forEach(function (c) {
          if (!list.some(function (l) { return l.title === c.title; })) list.push(c);
        });
        html += field(
          "Quests (" + state.chores.length + " of " + maxChores + ")",
          '<div class="chore-pick">' +
            list
              .map(function (c) {
                var on = !!chosen[c.title];
                return '<button type="button" aria-pressed="' + on + '" data-chore="' + esc(c.title) + '" data-icon="' + c.icon + '"' + (!on && state.chores.length >= maxChores ? " disabled" : "") + ">" + iconSvg(c.icon, "currentColor") + "<span>" + esc(c.title) + "</span></button>";
              })
              .join("") +
            '</div><form class="add-chore"><input type="text" maxlength="28" placeholder="Add your own quest" aria-label="Add your own quest" /><button type="submit"' + (state.chores.length >= maxChores ? " disabled" : "") + ">Add</button></form>"
        );
        html += field("Saving up for (optional)", '<input type="text" maxlength="30" data-k="goal" placeholder="e.g. Pizza night" value="' + esc(state.goal) + '" />');
      } else {
        html += field("The reward", '<input type="text" maxlength="30" data-k="reward" placeholder="e.g. Trip to the park" value="' + esc(state.reward) + '" />');
        html += field(
          "How many stickers?",
          '<div class="seg" role="radiogroup" aria-label="How many stickers">' +
            [10, 15, 20, 30]
              .map(function (n) {
                return '<button type="button" role="radio" aria-checked="' + (state.squares === n) + '" data-squares="' + n + '">' + n + "</button>";
              })
              .join("") +
            "</div>"
        );
      }
      html += '<button type="button" class="button primary print-btn" data-print>Print or save as PDF</button>';
      html += '<p class="maker-note">Free, no sign-up. Prints on A4. Choose “Save as PDF” in the print window to keep a copy.</p>';
      controls.innerHTML = html;
    }
    function renderSheet() {
      stage.innerHTML = kind === "chores" ? choreSheet(state) : rewardSheet(state);
      fit();
    }
    function fit() {
      var sheet = stage.firstChild;
      if (!sheet) return;
      sheet.style.transform = "none";
      var scale = Math.min(1, previewWrap.clientWidth / sheet.offsetWidth);
      sheet.style.transform = "scale(" + scale + ")";
      stage.style.height = sheet.offsetHeight * scale + "px";
    }
    function all() {
      renderControls();
      renderSheet();
    }

    controls.addEventListener("input", function (e) {
      var k = e.target.getAttribute("data-k");
      if (!k) return;
      state[k] = e.target.value;
      renderSheet();
    });
    controls.addEventListener("submit", function (e) {
      e.preventDefault();
      var input = e.target.querySelector("input");
      var title = input.value.trim();
      if (!title || state.chores.length >= maxChores) return;
      if (!state.chores.some(function (c) { return c.title.toLowerCase() === title.toLowerCase(); })) state.chores.push({ title: title, icon: "star" });
      all();
      var again = controls.querySelector(".add-chore input");
      if (again) again.focus();
    });
    controls.addEventListener("click", function (e) {
      var b = e.target.closest("button");
      if (!b || b.type === "submit") return;
      if (b.hasAttribute("data-print")) return printSheet(stage);
      if (b.getAttribute("data-buddy")) state.buddy = b.getAttribute("data-buddy");
      else if (b.getAttribute("data-theme")) state.theme = b.getAttribute("data-theme");
      else if (b.getAttribute("data-age")) {
        state.age = b.getAttribute("data-age");
        pickDefaults();
      } else if (b.getAttribute("data-squares")) state.squares = Number(b.getAttribute("data-squares"));
      else if (b.getAttribute("data-chore")) {
        var title = b.getAttribute("data-chore");
        var idx = state.chores.findIndex(function (c) { return c.title === title; });
        if (idx >= 0) state.chores.splice(idx, 1);
        else if (state.chores.length < maxChores) state.chores.push({ title: title, icon: b.getAttribute("data-icon") });
      } else return;
      all();
    });
    window.addEventListener("resize", fit);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);
    all();
    return stage;
  }

  var printRoot = document.createElement("div");
  printRoot.id = "print-root";
  document.body.appendChild(printRoot);
  var lastStage = null;
  function preparePrint(stage) {
    var sheet = (stage || lastStage) && (stage || lastStage).firstChild;
    printRoot.innerHTML = sheet ? sheet.outerHTML : "";
    var copy = printRoot.firstChild;
    if (copy) copy.style.transform = "none";
  }
  function printSheet(stage) {
    preparePrint(stage);
    window.print();
  }
  window.addEventListener("beforeprint", function () {
    if (!printRoot.firstChild) preparePrint();
  });
  window.addEventListener("afterprint", function () {
    printRoot.innerHTML = "";
  });

  Array.prototype.forEach.call(document.querySelectorAll("[data-maker]"), function (root) {
    lastStage = mount(root);
  });
})();
